const detectedVisitMaps=["data:image/png;base64,","data:image/png;base64,"];
const detectedRoutes=['detected-visits','detected-record'];
for(const route of detectedRoutes)window.SCREENS[route]={name:route==='detected-visits'?'Detected visits':'Record a detected visit',height:874,svg:'<svg xmlns="http://www.w3.org/2000/svg" width="402" height="874"></svg>'};
function detectedQueue(){
 if(!state.detectedVisits){const today=new Date(),earlier=new Date(today);earlier.setDate(earlier.getDate()-2);const date=d=>[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');state.detectedVisits=[{id:'detected-1',name:'London Health Sciences Centre',address:'800 Commissioners Rd E, London, ON N6A 5W9',date:date(today),time:'9:32 AM – 10:15 AM',map:0},{id:'detected-2',name:'Back in Motion Health – London, Ontario',address:'312 Oxford St W, London, ON N6H 4S4',date:date(earlier),time:'8:00 AM – 8:30 AM',map:1}];}
 return state.detectedVisits;
}
function detectedDate(value){return new Date(value+'T12:00:00').toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'});}
function detectedElement(tag,text,className){const el=document.createElement(tag);if(text)el.textContent=text;if(className)el.className=className;return el;}
function detectedAction(text,fn,secondary=false){const el=detectedElement('button',text,'detected-action'+(secondary?' secondary':''));el.type='button';el.onclick=fn;return el;}
function renderDetected(route){
 document.querySelector('.navigation-dock')?.remove();
 const page=detectedElement('section',null,'detected-page');const header=detectedElement('header',null,'detected-header');const back=detectedAction('‹',()=>{state.activeDetectedVisit=null;go('detected-visits'===route?'home':'detected-visits');},true);back.setAttribute('aria-label',route==='detected-visits'?'Back to Home':'Back to detected visits');header.append(back,detectedElement('h1',route==='detected-visits'?'Detected visits':'Record a detected visit'));page.append(header);host.append(page);
 const refreshSize=()=>{const height=Math.max(700,page.offsetHeight+32);host.dataset.height=height;host.style.height=height+'px';svg.setAttribute('height',height);svg.setAttribute('viewBox','0 0 402 '+height);resize();};
 if(route==='detected-visits'){
  page.append(detectedElement('p','Based on your location, we think you may have visited a healthcare facility. Please confirm with the details below.','detected-intro'));
  const queue=detectedQueue();if(!queue.length){page.append(detectedElement('h2','All visits reviewed'),detectedElement('p','You have no more detected visits to review.'),detectedAction('Back to Home',()=>go('home')));}
  for(const visit of queue){page.append(detectedElement('h2',detectedDate(visit.date),'detected-day'));const card=detectedElement('article',null,'detected-card');const map=document.createElement('img');map.src=detectedVisitMaps[visit.map];map.alt='Map near '+visit.name;map.className='detected-map';card.append(map);const body=detectedElement('div',null,'detected-card-body');body.append(detectedElement('h3',visit.name),detectedElement('p',visit.address),detectedElement('p',visit.time));const actions=detectedElement('div',null,'detected-actions');actions.append(detectedAction('Log visit',()=>{state.activeDetectedVisit=visit.id;go('detected-record');}),detectedAction('Not a visit',()=>{state.detectedVisits=queue.filter(v=>v.id!==visit.id);state.activeDetectedVisit=null;render('detected-visits');announce('Detected visit dismissed.');},true));body.append(actions);card.append(body);page.append(card);}
 }else{
  const visit=detectedQueue().find(v=>v.id===state.activeDetectedVisit);if(!visit){go('detected-visits');return;}
  const intro=detectedElement('p','Select your reason for visiting ','detected-intro');intro.append(detectedElement('strong',visit.name+' on '+detectedDate(visit.date)+' at '+visit.time));page.append(intro);
  const search=detectedElement('input',null,'detected-search');search.type='search';search.placeholder='Type of healthcare visit';search.setAttribute('aria-label','Search type of healthcare visit');page.append(search);const list=detectedElement('div');page.append(list);
  const headings={hospital:'Hospital',pharmacy:'Pharmacy',primary:'Primary Care',specialist:'Medical Specialists',rehab:'Rehabilitation & Therapy',clinic:'Specialty Clinics',other:'Other'};
  const draw=()=>{list.replaceChildren();let count=0;for(const [kind,names]of Object.entries(types)){const matches=names.filter(name=>name.toLowerCase().includes(search.value.trim().toLowerCase()));if(!matches.length)continue;count+=matches.length;list.append(detectedElement('h2',headings[kind],'detected-day'));const group=detectedElement('div',null,'detected-type-group');for(const name of matches){const option=detectedAction(name,()=>{state.type=name;state.visitRoute=kind;state.drafts[kind]={'Date of visit':visit.date,'Name of hospital':kind==='hospital'?visit.name:'','Detected location':visit.name,'Detected address':visit.address,'Detected time':visit.time};state.drafts.expenses={};go(kind);},true);option.append(detectedElement('span','›'));group.append(option);}list.append(group);}if(!count)list.append(detectedElement('p','No matching visit types.'));refreshSize();};search.oninput=draw;draw();
 }
 refreshSize();viewport.scrollTop=0;announce(route==='detected-visits'?'Detected visits':'Record a detected visit');
}
function completeDetectedVisit(){if(!state.activeDetectedVisit)return;state.detectedVisits=detectedQueue().filter(v=>v.id!==state.activeDetectedVisit);state.activeDetectedVisit=null;}
